dashboard.definition:
{
  "title": "DMX Inventory: Destinations",
  "description": "Current destinations and the pipelines that route to them. Unused destinations are flagged.",
  "visualizations": {
    "viz_list": {
      "type": "splunk.table",
      "title": "Destinations (select a row)",
      "dataSources": {
        "primary": "ds_list"
      },
      "options": {
        "count": 20
      },
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "did",
                "key": "row.object_id.value"
              }
            ]
          }
        }
      ]
    },
    "viz_raw": {
      "type": "splunk.table",
      "title": "Latest snapshot of selected destination (secrets redacted)",
      "dataSources": {
        "primary": "ds_raw"
      },
      "options": {
        "count": 20
      }
    },
    "viz_hist": {
      "type": "splunk.table",
      "title": "Change history of selected destination",
      "dataSources": {
        "primary": "ds_hist"
      },
      "options": {
        "count": 20
      }
    }
  },
  "dataSources": {
    "ds_list": {
      "type": "ds.search",
      "name": "ds_list",
      "options": {
        "query": "| inputlookup dmx_pipelines_current_lookup | fields name destination_ids | mvexpand destination_ids | stats values(name) as used_by by destination_ids | rename destination_ids as ref | append [| inputlookup dmx_destinations_current_lookup | eval ref=mvappend(object_id, name) | mvexpand ref | eval is_dest=1 | fields ref is_dest object_id name destination_type status last_seen] | stats values(used_by) as used_by max(is_dest) as is_dest values(object_id) as object_id values(name) as name values(destination_type) as destination_type values(status) as status values(last_seen) as last_seen by ref | where is_dest=1 | stats values(used_by) as used_by_pipelines values(name) as name values(destination_type) as destination_type values(status) as status values(last_seen) as last_seen by object_id | eval used_by_count=coalesce(mvcount(used_by_pipelines), 0), unused=if(used_by_count=0, \"yes\", \"no\") | table object_id name destination_type status used_by_count used_by_pipelines unused last_seen | sort name",
        "queryParameters": {
          "earliest": "-24h",
          "latest": "now"
        }
      }
    },
    "ds_raw": {
      "type": "ds.search",
      "name": "ds_raw",
      "options": {
        "query": "`dmx_index` sourcetype=dmx:destination object_id=\"$did$\" | head 1 | table _time _raw",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    },
    "ds_hist": {
      "type": "ds.search",
      "name": "ds_hist",
      "options": {
        "query": "`dmx_index` sourcetype=dmx:change object_type=destination object_id=\"$did$\" | table _time change_type name changed_fields collection_id",
        "queryParameters": {
          "earliest": "$global_time.earliest$",
          "latest": "$global_time.latest$"
        }
      }
    }
  },
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-7d@h,now"
      }
    }
  },
  "defaults": {
    "tokens": {
      "default": {
        "did": {
          "value": "none-selected"
        }
      }
    }
  },
  "layout": {
    "type": "grid",
    "options": {
      "width": 1440
    },
    "structure": [
      {
        "item": "viz_list",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 1440,
          "h": 420
        }
      },
      {
        "item": "viz_raw",
        "type": "block",
        "position": {
          "x": 0,
          "y": 420,
          "w": 1440,
          "h": 260
        }
      },
      {
        "item": "viz_hist",
        "type": "block",
        "position": {
          "x": 0,
          "y": 680,
          "w": 1440,
          "h": 300
        }
      }
    ],
    "globalInputs": [
      "input_time"
    ]
  }
}
